"AI-Coding-Guide-Zh/docs/openclaw/10-安全配置指南.md",
];
const out: string[] = [];
for (const f of fs) {
  const r = await tools.grep({ pattern: "^#{1,3} ", path: f });
  out.push("=== " + f + " ===");
  out.push(r.matches.map(m => m.lineNumber + ": " + m.line).join("\n"));
}
console.log(out.join("\n"));", "description": "List headings in OpenClaw docs"}

